def even_binomial_Coeff_Sum(n):
    """Write a python function to find sum of even index binomial coefficients.

    Return C(n, 0) + C(n, 2) + C(n, 4) + ... .

    For n >= 1 the even- and odd-index sums are equal and together
    total 2**n, so each is 2**(n - 1). For n == 0 the sum is
    C(0, 0) == 1.
    """
    if n < 0:
        raise ValueError("n must be non-negative")
    if n == 0:
        return 1
    return 1 << (n - 1)
